__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"TIPS",{enumerable:!0,get:function(){return n}});const n=[{id:1,when:'zahltag',text:"Leg die Sparrate direkt am Zahltag zur Seite \u2013 bevor das Geld verplant ist."},{id:2,when:'zahltag',text:"Richte einen Dauerauftrag f\xfcr den Tag nach dem Gehaltseingang ein. Was weg ist, vermisst du kaum."},{id:3,when:'zahltag',text:"Heute ist Zahltag: Erst sparen, dann ausgeben \u2013 nicht umgekehrt."},{id:4,when:'zahltag',text:"Geh am Zahltag einmal deine Fixkosten durch. Was davon brauchst du wirklich?"},{id:5,when:'zahltag',text:"G\xf6nn dir am Zahltag eine Kleinigkeit \u2013 aber leg vorher fest, wie viel."},{id:6,when:'zahltag',text:"Teil dein Geld am Zahltag auf: Fixkosten, Leben, Sparen. Dann wei\xdft du, was \xfcbrig ist."},{id:7,when:'zahltag',text:"Gehaltserh\xf6hung bekommen? Spar die H\xe4lfte davon, bevor du dich an das Mehr gew\xf6hnst."},{id:8,when:'zahltag',text:"Heb am Zahltag dein Wochenbudget in bar ab \u2013 wenn\u2019s alle ist, ist\u2019s alle."},{id:9,when:'wochenende',text:"Plan ein festes Budget f\xfcrs Wochenende und nimm es in bar mit."},{id:10,when:'wochenende',text:"Picknick statt Restaurant: gleiche Freunde, halber Preis."},{id:11,when:'wochenende',text:"Ein Spieleabend zu Hause ist oft lustiger als die Bar \u2013 und deutlich g\xfcnstiger."},{id:12,when:'wochenende',text:"Schau, was deine Stadt am Wochenende kostenlos anbietet: M\xe4rkte, Museen, Konzerte."},{id:13,when:'wochenende',text:"Iss vor dem Ausgehen zu Hause. Wer satt losgeht, gibt unterwegs weniger aus."},{id:14,when:'wochenende',text:"Ein Wochenende ohne Shopping-Apps: einfach mal l\xf6schen und schauen, ob was fehlt."},{id:15,when:'wochenende',text:"Ein Ausflug in die Natur kostet oft nur die Anfahrt."},{id:16,when:'wochenende',text:"Lade Freunde zum Mitbring-Essen ein: Jeder bringt etwas, keiner zahlt viel."},{id:17,when:'lieferdienst',text:"Koch einmal die Woche vor, dann ist der Lieferdienst am Abend weniger verlockend."},{id:18,when:'lieferdienst',text:"Leg dir ein paar Notfall-Gerichte in den Gefrierschrank \u2013 schneller als jede Lieferung."},{id:19,when:'lieferdienst',text:"Nimm die Lieferdienst-App vom Startbildschirm. Ein Klick mehr hilft schon."},{id:20,when:'lieferdienst',text:"Lieblingsgericht vom Lieferdienst? Such das Rezept und koch\u2019s selbst nach."},{id:21,when:'lieferdienst',text:"Bestell nur noch am Wochenende \u2013 unter der Woche wird gekocht."},{id:22,when:'lieferdienst',text:"Rechne mal aus, was du im Monat f\xfcr Lieferungen ausgibst. Das motiviert."},{id:23,when:'kaffee',text:"Nimm deinen Kaffee im Thermobecher von zu Hause mit."},{id:24,when:'kaffee',text:"Mit guten Bohnen schmeckt der Kaffee zu Hause oft besser als unterwegs."},{id:25,when:'kaffee',text:"Coffee to go nur an einem festen Tag pro Woche \u2013 dann wird\u2019s wieder was Besonderes."},{id:26,when:'kaffee',text:"Viele B\xe4ckereien und Caf\xe9s geben Rabatt, wenn du deinen eigenen Becher mitbringst."},{id:27,when:'kaffee',text:"Ganze Bohnen statt Kapseln sind pro Tasse meist deutlich g\xfcnstiger."},{id:28,when:'allgemein',text:"Geh nie hungrig einkaufen."},{id:29,when:'allgemein',text:"Schreib eine Einkaufsliste und halte dich dran."},{id:30,when:'allgemein',text:"Vergleich den Preis pro Kilo oder Liter, nicht den Packungspreis."},{id:31,when:'allgemein',text:"Die g\xfcnstigen Produkte stehen oft ganz oben oder ganz unten im Regal."},{id:32,when:'allgemein',text:"Eigenmarken sind oft genauso gut wie Markenprodukte."},{id:33,when:'allgemein',text:"Plan deine Mahlzeiten f\xfcr die Woche \u2013 dann kaufst du gezielter ein."},{id:34,when:'allgemein',text:"Koch gr\xf6\xdfere Portionen und nimm den Rest mit zur Arbeit."},{id:35,when:'allgemein',text:"Brotdose statt Kantine \u2013 schon ein paar Tage pro Woche machen viel aus."},{id:36,when:'allgemein',text:"Leg einen Reste-Tag ein: Einmal pro Woche wird gegessen, was noch da ist."},{id:37,when:'allgemein',text:"Kurz vor Ladenschluss gibt\u2019s oft Rabatte auf Frisches."},{id:38,when:'allgemein',text:"Apps gegen Lebensmittelverschwendung bieten \xdcberraschungst\xfcten f\xfcr wenig Geld."},{id:39,when:'allgemein',text:"Saisonales Obst und Gem\xfcse ist meist g\xfcnstiger und schmeckt besser."},{id:40,when:'allgemein',text:"Leitungswasser statt Flaschen \u2013 spart Geld und Schlepperei."},{id:41,when:'allgemein',text:"Kauf haltbare Grundnahrungsmittel im Angebot auf Vorrat."},{id:42,when:'allgemein',text:"Ein gro\xdfer Einkauf pro Woche statt jeden Tag kurz in den Laden \u2013 weniger Spontank\xe4ufe."},{id:43,when:'allgemein',text:"Nimm einen Korb statt eines Einkaufswagens, wenn du nur wenig brauchst."},{id:44,when:'allgemein',text:"Frier Brot, Obst und Reste ein, bevor sie schlecht werden."},{id:45,when:'allgemein',text:"Mindesthaltbarkeit hei\xdft nicht \u201esofort wegwerfen\u201c \u2013 erst schauen, riechen, probieren."},{id:46,when:'allgemein',text:"Zieh Kr\xe4uter auf der Fensterbank, statt sie jedes Mal neu zu kaufen."},{id:47,when:'allgemein',text:"Pack Snacks f\xfcr unterwegs selbst ein, statt am Bahnhof zu kaufen."},{id:48,when:'allgemein',text:"Beim Online-Einkauf siehst du den Gesamtpreis, bevor du bezahlst \u2013 das hilft beim Rechnen."},{id:49,when:'allgemein',text:"Getr\xe4nke sind im Restaurant teuer \u2013 Wasser bestellen spart oft am meisten."},{id:50,when:'allgemein',text:"Gew\xfcrze und N\xfcsse gibt\u2019s im Asia- oder Gro\xdfmarkt oft viel g\xfcnstiger."},{id:51,when:'allgemein',text:"Bei Aktionen wie \u201e3 f\xfcr 2\u201c nur zugreifen, wenn du\u2019s wirklich brauchst."},{id:52,when:'allgemein',text:"Fr\xfchst\xfcck zu Hause statt beim B\xe4cker unterwegs \u2013 das l\xe4ppert sich."},{id:53,when:'allgemein',text:"24-Stunden-Regel: Schlaf eine Nacht dr\xfcber, bevor du spontan etwas kaufst."},{id:54,when:'allgemein',text:"Leg Wunschteile erst in den Warenkorb und schau nach einer Woche wieder rein."},{id:55,when:'allgemein',text:"Rechne Preise in Arbeitsstunden um. Ist dir die Jacke das noch wert?"},{id:56,when:'allgemein',text:"Melde dich von Newslettern ab, die dich nur zum Kaufen verleiten."},{id:57,when:'allgemein',text:"Speicher keine Kartendaten in Online-Shops \u2013 der kleine Umweg bremst Spontank\xe4ufe."},{id:58,when:'allgemein',text:"Frag dich vor jedem Kauf: Brauche ich das oder will ich es nur gerade?"},{id:59,when:'allgemein',text:"Shoppen aus Langeweile? Geh lieber eine Runde spazieren."},{id:60,when:'allgemein',text:"\u201eReduziert\u201c hei\xdft nicht \u201egespart\u201c \u2013 gespart ist nur, was du nicht ausgibst."},{id:61,when:'allgemein',text:"F\xfchr eine Wunschliste. Was nach einem Monat noch draufsteht, darfst du dir \xfcberlegen."},{id:62,when:'allgemein',text:"Zahl \xf6fter bar \u2013 Scheine hergeben f\xfchlt sich echter an als Karte."},{id:63,when:'allgemein',text:"Vergleich vor gr\xf6\xdferen K\xe4ufen mindestens drei Angebote."},{id:64,when:'allgemein',text:"Lass dich nicht von \u201eNur heute!\u201c hetzen. Gute Angebote kommen wieder."},{id:65,when:'allgemein',text:"Gebraucht kaufen lohnt sich: Elektronik, M\xf6bel und Kleidung gibt\u2019s oft fast wie neu."},{id:66,when:'allgemein',text:"Verkauf, was du nicht mehr brauchst \u2013 das Geld kann direkt ins Sparziel."},{id:67,when:'allgemein',text:"Leih dir Werkzeug oder selten genutzte Dinge, statt sie zu kaufen."},{id:68,when:'allgemein',text:"Trag deine Ausgaben eine Woche lang ein. Du wirst \xfcberrascht sein."},{id:69,when:'allgemein',text:"Kleine Betr\xe4ge summieren sich: 3 \u20ac am Tag sind \xfcber 1.000 \u20ac im Jahr."},{id:70,when:'allgemein',text:"Belohn dich f\xfcr Sparerfolge \u2013 aber mit etwas, das wenig kostet."},{id:71,when:'allgemein',text:"Erz\xe4hl Freunden von deinem Sparziel. Das macht es verbindlicher."},{id:72,when:'allgemein',text:"Konkrete Ziele mit Betrag und Datum motivieren mehr als \u201eirgendwann mal sparen\u201c."},{id:73,when:'allgemein',text:"Geh einmal im Monat deine Abos durch. Was hast du lange nicht genutzt?"},{id:74,when:'allgemein',text:"Streaming-Dienste lieber abwechselnd als gleichzeitig abonnieren."},{id:75,when:'allgemein',text:"Kostenlose Probeabos direkt nach dem Abschluss k\xfcndigen \u2013 dann vergisst du\u2019s nicht."},{id:76,when:'allgemein',text:"Viele Vertr\xe4ge kannst du nach der Mindestlaufzeit monatlich k\xfcndigen. Nachsehen lohnt sich."},{id:77,when:'allgemein',text:"Vergleich deinen Handyvertrag \u2013 oft gibt\u2019s f\xfcr weniger Geld mehr Datenvolumen."},{id:78,when:'allgemein',text:"Familien- oder Partnertarife sind oft g\xfcnstiger als einzelne Abos."},{id:79,when:'allgemein',text:"Pr\xfcf deine Versicherungen: doppelt versichert ist doppelt bezahlt."},{id:80,when:'allgemein',text:"J\xe4hrliche statt monatlicher Zahlung ist bei manchen Vertr\xe4gen g\xfcnstiger."},{id:81,when:'allgemein',text:"Fitnessstudio kaum genutzt? Laufen drau\xdfen und \xdcbungen zu Hause kosten nichts."},{id:82,when:'allgemein',text:"Viele Zeitschriften kannst du in der Bibliothek lesen."},{id:83,when:'allgemein',text:"Frag beim Anbieter nach einem besseren Tarif, bevor du k\xfcndigst \u2013 oft gibt\u2019s ein Angebot."},{id:84,when:'allgemein',text:"In den Einstellungen deines Handys findest du alle App-Abos auf einen Blick."},{id:85,when:'allgemein',text:"Zahlst du Kontof\xfchrungsgeb\xfchren? Vergleich, ob es g\xfcnstigere Konten gibt."},{id:86,when:'allgemein',text:"Strom- und Gasanbieter regelm\xe4\xdfig vergleichen."},{id:87,when:'allgemein',text:"Trag K\xfcndigungsfristen in den Kalender ein \u2013 dann verpasst du keine."},{id:88,when:'allgemein',text:"Doppelte Cloud-Speicher? Aufr\xe4umen spart oft ein ganzes Abo."},{id:89,when:'allgemein',text:"Pr\xfcf deine Kfz-Versicherung jedes Jahr \u2013 ein Wechsel kann sich lohnen."},{id:90,when:'allgemein',text:"Ger\xe4te ganz ausschalten statt Stand-by \u2013 eine Steckerleiste mit Schalter hilft."},{id:91,when:'allgemein',text:"Heizung ein Grad runter spart sp\xfcrbar Energie."},{id:92,when:'allgemein',text:"Sto\xdfl\xfcften statt Fenster dauerhaft auf Kipp."},{id:93,when:'allgemein',text:"W\xe4sche bei niedrigerer Temperatur waschen reicht meistens v\xf6llig."},{id:94,when:'allgemein',text:"W\xe4sche an der Luft trocknen statt im Trockner."},{id:95,when:'allgemein',text:"Mit Deckel kochen spart Energie."},{id:96,when:'allgemein',text:"Wasser im Wasserkocher erhitzen statt auf dem Herd."},{id:97,when:'allgemein',text:"LED-Lampen verbrauchen deutlich weniger Strom als alte Gl\xfchbirnen."},{id:98,when:'allgemein',text:"Duschen statt baden \u2013 und ruhig ein bisschen k\xfcrzer."},{id:99,when:'allgemein',text:"Sp\xfcl- und Waschmaschine nur voll laufen lassen."},{id:100,when:'allgemein',text:"Stell den K\xfchlschrank nicht k\xe4lter als n\xf6tig ein \u2013 etwa 7 Grad reichen meist."},{id:101,when:'allgemein',text:"Lies deine Z\xe4hler regelm\xe4\xdfig ab, dann gibt\u2019s bei der Abrechnung keine \xdcberraschung."},{id:102,when:'allgemein',text:"Reparieren statt neu kaufen \u2013 Repair-Caf\xe9s helfen oft kostenlos."},{id:103,when:'allgemein',text:"Teil Dinge mit Nachbarn: Leiter, Bohrmaschine, Rasenm\xe4her."},{id:104,when:'allgemein',text:"Stell den Router per Zeitschaltung nachts ab."},{id:105,when:'allgemein',text:"Kurze Wege zu Fu\xdf oder mit dem Rad \u2013 spart Sprit und Parkgeb\xfchren."},{id:106,when:'allgemein',text:"Tanken ist abends oft g\xfcnstiger als morgens. Preis-Apps zeigen\u2019s dir."},{id:107,when:'allgemein',text:"Fahrgemeinschaften f\xfcr den Arbeitsweg sparen Geld und Nerven."},{id:108,when:'allgemein',text:"Pr\xfcf den Reifendruck: Zu wenig Luft kostet Sprit."},{id:109,when:'allgemein',text:"Bahntickets fr\xfch buchen \u2013 Sparpreise sind oft deutlich g\xfcnstiger."},{id:110,when:'allgemein',text:"Pr\xfcf, ob sich ein Monats- oder Jahresticket f\xfcr dich lohnt."},{id:111,when:'allgemein',text:"Vorausschauend fahren spart Sprit: fr\xfch vom Gas, wenig bremsen."},{id:112,when:'allgemein',text:"Raus mit unn\xf6tigem Gewicht aus dem Kofferraum \u2013 und die Dachbox runter, wenn du sie nicht brauchst."},{id:113,when:'allgemein',text:"Carsharing statt Zweitwagen kann viel g\xfcnstiger sein."},{id:114,when:'allgemein',text:"Vergleich Parkhaus-Preise oder nutz Park & Ride."},{id:115,when:'allgemein',text:"Kauf Kleidung, die zu dem passt, was du schon hast."},{id:116,when:'allgemein',text:"Qualit\xe4t statt Masse: Ein gutes Teil h\xe4lt oft l\xe4nger als drei billige."},{id:117,when:'allgemein',text:"Kleidertausch mit Freunden \u2013 neue Teile ohne Kosten."},{id:118,when:'allgemein',text:"Secondhand-L\xe4den und -Apps haben oft tolle Fundst\xfccke."},{id:119,when:'allgemein',text:"Pflege Schuhe und Kleidung, dann halten sie l\xe4nger."},{id:120,when:'allgemein',text:"Kauf Wintersachen im Fr\xfchjahr und Sommersachen im Herbst."},{id:121,when:'allgemein',text:"F\xfcr die meisten Putzarbeiten reichen Essig, Natron und Sp\xfclmittel."},{id:122,when:'allgemein',text:"Nachf\xfcllpacks sind oft g\xfcnstiger als neue Flaschen."},{id:123,when:'allgemein',text:"Mit einem Bibliotheksausweis bekommst du B\xfccher, Filme und H\xf6rb\xfccher f\xfcr wenig Geld."},{id:124,when:'allgemein',text:"Viele Museen haben einen Tag mit freiem oder erm\xe4\xdfigtem Eintritt."},{id:125,when:'allgemein',text:"Kauf Spiele im Sale \u2013 nach ein paar Monaten werden sie oft g\xfcnstiger."},{id:126,when:'allgemein',text:"Deaktivier In-App-K\xe4ufe, damit nichts aus Versehen passiert."},{id:127,when:'allgemein',text:"Teil Hobbys mit Freunden: Ausr\xfcstung leihen statt kaufen."},{id:128,when:'allgemein',text:"Geh am g\xfcnstigen Kinotag oder nutz eine Kundenkarte."},{id:129,when:'allgemein',text:"Sport drau\xdfen kostet nichts: Laufen, Radfahren, \xdcbungen im Park."},{id:130,when:'allgemein',text:"Kostenlose Lern-Apps und Videos ersetzen manchen teuren Kurs."},{id:131,when:'allgemein',text:"Kauf Tickets f\xfcr Konzerte und Events fr\xfch \u2013 dann sind sie oft g\xfcnstiger."},{id:132,when:'allgemein',text:"Lies vor dem Kauf Testberichte \u2013 Fehlk\xe4ufe sind am teuersten."},{id:133,when:'dezember',text:"Leg f\xfcr Weihnachtsgeschenke ein festes Budget pro Person fest."},{id:134,when:'dezember',text:"Wichteln statt \u201ejeder beschenkt jeden\u201c."},{id:135,when:'dezember',text:"Selbstgemachte Geschenke kommen oft besser an als gekaufte."},{id:136,when:'dezember',text:"Kauf Geschenke \xfcbers Jahr, wenn du gute Angebote siehst \u2013 nicht alles im Dezember."},{id:137,when:'dezember',text:"Verschenk gemeinsame Zeit: Ein Ausflug ist oft mehr wert als ein Gegenstand."},{id:138,when:'dezember',text:"Trag Geburtstage in den Kalender ein \u2013 Last-Minute-Geschenke sind oft teurer."},{id:139,when:'dezember',text:"Nach Weihnachten gibt\u2019s Deko und Geschenkpapier stark reduziert \u2013 f\xfcrs n\xe4chste Jahr."},{id:140,when:'dezember',text:"Weihnachtsmarkt? Nimm ein festes Budget in bar mit."},{id:141,when:'extra',text:"Extra-Geld bekommen? Leg den Gro\xdfteil gleich zur Seite, bevor es verplant ist."},{id:142,when:'extra',text:"Bonus, Steuererstattung oder Geldgeschenk: Teil\u2019s auf \u2013 etwas zum G\xf6nnen, der Rest f\xfcrs Ziel."},{id:143,when:'monatsende',text:"Monatsende knapp? Schau nach, wohin das Geld diesen Monat gegangen ist."},{id:144,when:'monatsende',text:"Was am Monatsende \xfcbrig ist, gleich zur Seite legen \u2013 sonst verschwindet es."},{id:145,when:'allgemein',text:"Mach jedes Jahr deine Steuererkl\xe4rung \u2013 viele bekommen Geld zur\xfcck."},{id:146,when:'allgemein',text:"Leg einen kleinen Notgroschen an, dann musst du bei \xdcberraschungen nicht ans Sparziel."},{id:147,when:'allgemein',text:"Vergleich Tagesgeld-Zinsen \u2013 die Unterschiede zwischen Banken sind oft gro\xdf."},{id:148,when:'allgemein',text:"Ein Unterkonto nur f\xfcrs Sparen trennt Spargeld vom Alltagsgeld."},{id:149,when:'allgemein',text:"Feier kleine Erfolge \u2013 jeder gesicherte Euro bringt dich n\xe4her ans Ziel."},{id:150,when:'allgemein',text:"Rund beim Sichern auf \u2013 aus 3,50 \u20ac werden 4 \u20ac, die 50 Cent wandern mit ins Ziel."}]},909,[]);